SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(4*10^9);Alarm(180);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");root:="work/deg10/continuation_20261031b/C60/";a:=eval Read(root cat "three_maps_remaining.m");pts:=a[1];cases:=a[2];k:=GF(7);PR:=PolynomialRing(k);active:={};for row in cases do for v in row[2]do assert v[2]eq 1;Include(~active,v[1]);end for;end for;obs:=[* *];passed:=AssociativeArray();
for si in Sort(Setseq(active))do d,bits,pol,co:=Explode(pts[si]);K<z>:=ext<k|PR!pol>;bc:=[Evaluate(PR!v,z):v in co];b,c:=Explode(bc);E0:=EllipticCurve([K|0,c,0,b*(1-b-c),0]);P2:=E0![0,0];Q:=E0![b,b];assert Order(P2)eq 2 and Order(Q)eq 30 and P2 ne 15*Q;RX<x>:=PolynomialRing(K);E,phi:=IsogenyFromKernel(E0,x-P2[1]);psi:=DualIsogeny(phi);S:=phi(Q);assert Order(S)eq 30 and psi(S)eq 2*Q;b2,b4,b6,b8:=Explode(bInvariants(E));ai:=aInvariants(E);half:=x^4-b4*x^2-2*b6*x-b8-S[1]*(4*x^3+b2*x^2+2*b4*x+b6);lifts:=[* *];
 for rr in Roots(half)do xx:=rr[1];f:=x^2+(ai[1]*xx+ai[3])*x-(xx^3+ai[2]*xx^2+ai[4]*xx+ai[5]);for yy in Roots(f)do P:=E![xx,yy[1]];if 2*P ne S then continue;end if;if psi(P)ne Q then continue;end if;assert Order(P)eq 60;Append(~lifts,[*TateNormalForm_bc(E,P),Eltseq(P)*]);end for;end for;assert #lifts in[0,2];passed[si]:=#lifts eq 2;Append(~obs,[*si,d,[Degree(v[1]):v in Factorization(half)],#lifts*]);print "D31B_C60_FINAL_HALF_POINT",si,d,#lifts,Cputime(tt);
end for;
left:=[* *];tests:=[* *];for row in cases do flags:=[passed[v[1]]:v in row[2]];ok:=&and flags;Append(~tests,[*row[1],row[2],flags,ok*]);if ok then Append(~left,row);end if;end for;Write(root cat "final_halving.m",Sprint([*obs,tests,left*]):Overwrite:=true);print "D31B_C60_FINAL_HALF_COMPLETE",#obs,#tests,#left,Cputime(tt);quit;
